function validate(input) {
  const [{ Genders = [] }] = input;
  const ids = new Set(), counts = { female: 0, other: 0, male: 0 };
  for (const [id, gender] of Genders) {
    if (id === null) return 'Every user needs a user_id.';
    if (ids.has(id)) return `user_id ${id} appears twice in Genders.`;
    ids.add(id);
    if (!Object.hasOwn(counts, gender)) return `User ${id} has gender ${gender}; use female, other or male.`;
    counts[gender]++;
  }
  if (counts.female !== counts.other || counts.other !== counts.male) return 'Each gender needs the same number of users.';
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const perGender = small ? Math.floor(rand() * 3) : 666;
  const total = perGender * 3;
  // Distinct ids drawn from a slightly larger pool, so gaps appear and genders interleave.
  const pool = [];
  for (let id = 1; id <= total + (small ? 4 : 500); id++) pool.push(id);
  for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const Genders = [];
  ['female', 'other', 'male'].forEach((gender, g) => {
    for (let i = 0; i < perGender; i++) Genders.push([pool[g * perGender + i], gender]);
  });
  for (let i = Genders.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Genders[i], Genders[j]] = [Genders[j], Genders[i]]; }
  return [{ Genders }];
}
